import os
import re
from html.parser import HTMLParser
from typing import List, Tuple, Optional

import deepl


class _MarkupTokenizer(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=False)
        self.tokens: List[Tuple[str, str]] = []

    def handle_starttag(self, tag, attrs):
        attrs_str = "".join(
            f' {name}' if value is None else f' {name}="{value}"' for name, value in attrs
        )
        self.tokens.append(("tag", f"<{tag}{attrs_str}>"))

    def handle_startendtag(self, tag, attrs):
        attrs_str = "".join(
            f' {name}' if value is None else f' {name}="{value}"' for name, value in attrs
        )
        self.tokens.append(("tag", f"<{tag}{attrs_str}/>"))

    def handle_endtag(self, tag):
        self.tokens.append(("tag", f"</{tag}>"))

    def handle_data(self, data):
        if data:
            self.tokens.append(("text", data))

    def handle_entityref(self, name):
        self.tokens.append(("text", f"&{name};"))

    def handle_charref(self, name):
        self.tokens.append(("text", f"&#{name};"))

    def handle_comment(self, data):
        self.tokens.append(("tag", f"<!--{data}-->"))

    def handle_decl(self, decl):
        self.tokens.append(("tag", f"<!{decl}>"))

    def handle_pi(self, data):
        self.tokens.append(("tag", f"<?{data}?>"))


def _escape_attr_value(value: str) -> str:
    return (
        value.replace("&", "&amp;")
        .replace('"', "&quot;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
    )


def _normalize_output_text(text: str) -> str:
    return text.replace("\u2028", "\n").replace("\u2029", "\n")


def translate_markup(
    markup: str,
    target_lang: str,
    source_lang: Optional[str] = None,
    preserve_formatting_tags: bool = True,
) -> str:
    auth_key = os.getenv("DEEPL_AUTH_KEY")
    if not auth_key:
        raise EnvironmentError("DEEPL_AUTH_KEY is required")

    translator = deepl.Translator(auth_key)

    parser = _MarkupTokenizer()
    parser.feed(markup)
    parser.close()

    translated_parts: List[str] = []
    text_buffer: List[str] = []

    def flush_text_buffer():
        if not text_buffer:
            return
        original = "".join(text_buffer)
        text_buffer.clear()
        if original.strip() == "":
            translated_parts.append(original)
            return
        result = translator.translate_text(
            original,
            source_lang=source_lang,
            target_lang=target_lang,
            tag_handling="html" if preserve_formatting_tags else None,
            preserve_formatting=preserve_formatting_tags,
        )
        translated_parts.append(_normalize_output_text(result.text))

    for kind, value in parser.tokens:
        if kind == "text":
            text_buffer.append(value)
        else:
            flush_text_buffer()
            translated_parts.append(value)

    flush_text_buffer()
    return "".join(translated_parts)


def translate_html(markup: str, target_lang: str, source_lang: Optional[str] = None) -> str:
    return translate_markup(markup, target_lang=target_lang, source_lang=source_lang)
